{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "This bill would require local education agencies (LEAs) to classify school nurses as licensed personnel and pay them according to the LEA's salary schedule for licensed personnel.",
      "rationale": "Conveys the required classification and salary schedule; the surrounding summary identifies LEA-employed nurses and excludes contractors."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "These rules do not apply to LEA contractors or the LEA's ability to contract with the Tennessee public school nurse program.",
      "rationale": "Conveys the contractor exclusion and preserves the ability to contract with the program, but omits the express protection for setting contract terms, including nurse compensation."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "School nurses employed by an LEA who are registered nurses and Nationally Certified School Nurses with zero years of experience must receive the same base salary as licensed teachers with a bachelor's degree and zero years of experience.",
      "rationale": "Conveys LEA employment, the required nursing and school-nurse credentials, zero experience, and the teacher base-salary benchmark."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Nurses with more training and experience than these requirements must receive more than that base salary",
      "rationale": "Conveys mandatory pay above the base salary for nurses exceeding the previously described training and experience benchmark."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Nurses with more training and experience than these requirements must receive more than that base salary, while those with less must receive less.",
      "rationale": "Conveys mandatory pay below the base salary for nurses with less training and experience than the benchmark."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill prohibits an LEA from reducing a school nurse's salary when adopting a salary schedule.",
      "rationale": "Conveys the protection against salary reductions for existing school nurses when the LEA adopts the schedule."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2026, and apply to the 2026-2027 school year and beyond.",
      "rationale": "Includes the effective date, first applicable school year, and continuing application."
    }
  ]
}
